"建議搭早班電車前往": [
"早い電車での訪問がおすすめ",
"An early train is recommended"
],
"勝守漁港的漁船與後方的高架車站": [
"勝守漁港の漁船と、奥の高架駅",
"Fishing boats at Katsumori Fishing Port with the elevated station beyond"
],
"港邊的漁船，後方是高架軌道與車站": [
"港の漁船、その奥に高架線路と駅",
"Boats in the harbor, with elevated tracks and a station beyond"
],
"あまとりざきじんじゃ": [
"あまとりざきじんじゃ",
"Amatorizaki-jinja"
],
"神社・海岸": [
"神社・海岸",
"Shrine · Coast"
],
"面向海岸的神社，黃昏的夕陽與參拜街道是最大的看點。": [
"海に面した神社。夕暮れの夕日と参道が一番の見どころ。",
"A shrine facing the sea. Sunset and the approach road are the highlights."
],
"天鳥崎神社位於海岸邊，參拜者沿著街道一路走向鳥居與社殿，鹹鹹的海風會陪著你走完整段路。": [
"天鳥崎神社は海岸沿いにあり、参拝者は参道を歩いて鳥居と社殿へ向かいます。潮風が道のりのあいだずっと寄り添います。",
"Amatorizaki Shrine stands on the coast; worshippers walk the approach road to the torii and shrine buildings, accompanied by salty sea breezes all the way."
],
"傍晚是這裡最迷人的時段：夕陽把海面與屋瓦染成橘紅色，社殿的剪影映在天色裡。參拜之後可以回到參拜街道，逛逛沿路的小店，再搭電車回程。從天鳥崎中央站步行即可抵達。": [
"夕方は最も魅力的な時間帯です。夕日が海面と屋根瓦を橙赤色に染め、社殿のシルエットが空に浮かびます。参拝のあとは参道に戻って、沿道の小さな店をのぞき、電車で帰るのもよいでしょう。天鳥崎中央駅から歩いて行けます。",
"Evening is the most enchanting time: the setting sun paints the sea and roof tiles orange-red and the shrine’s silhouette stands against the sky. After worship, return along the approach road, browse the small shops, then take the train home. It is a walk from Tentori-Chuo station."
],
