"美食・購物・緣結": [
"グルメ・ショッピング・縁結び",
"Food · Shopping · Matchmaking"
],
"美食、商店與緣結神社齊聚的熱鬧商圈。": [
"グルメ、店、縁結びの神社が集まるにぎやかな商店街。",
"A lively district gathering food, shops and a matchmaking shrine."
],
"九里橋商圈沿著高架軌道向外展開：屋頂庭園上有成排的櫻花與攤位，樓下是密密麻麻的餐廳與商店，想吃的、想逛的一次就能解決。": [
"九里橋商店街は高架線路に沿って広がります。屋上庭園には桜並木と屋台が並び、階下には飲食店と店舗がぎっしり。食べたいものも見たいものも一度に済みます。",
"The Kusatobashi district spreads along the elevated tracks. Rooftop gardens have rows of cherry trees and stalls, while below are packed restaurants and shops—everything you want to eat and see in one go."
],
"商圈裡有一間祈求良緣的緣結神社，朱紅色的牌坊隱身在大樓之間，許多人會在購物前後順道來參拜、買個御守。從九里橋三丁目站出站後，沿著人潮走就能到。": [
"商店街には良縁を願う縁結びの神社があり、朱塗りの鳥居がビルの間にひっそりと立っています。買い物の前後に立ち寄ってお守りを求める人が大勢います。九里橋三丁目駅を出たら、人の流れに沿って進めば着きます。",
"The district has a matchmaking shrine for good fortune in love, its vermilion torii tucked between buildings. Many people drop in before or after shopping to buy an omamori charm. From Kusatobashi 3-chome station, just follow the crowd."
],
