"河濱・四季": [
"川辺・四季",
"Riverside · Seasons"
],
"安靜的川濱步道，可以欣賞夕陽與穿越鐵橋的列車。": [
"静かな川辺の遊歩道で、夕日と鉄橋を渡る列車が見られます。",
"A quiet riverside promenade with sunsets and trains crossing the iron bridge."
],
"多見瀨河濱公園是一處沿著河岸展開的安靜步道。寬闊的河面映著天空，石階一路通到水邊，不用走遠就能找到一個坐下來發呆的地方。遠處的鐵橋橫跨河面，電車緩緩駛過，是這裡最有代表性的風景。": [
"多見瀨河畔公園は川岸に沿って続く静かな遊歩道です。広い川面に空が映り、石段が水辺まで続いていて、遠くへ行かなくてもぼんやり座れる場所が見つかります。遠くの鉄橋が川をまたぎ、電車がゆっくり渡っていく光景が、ここを代表する景色です。",
"Tomise Riverside Park is a quiet promenade along the riverbank. The wide river mirrors the sky and stone steps lead to the water, so a place to sit and daydream is never far. In the distance an iron bridge spans the river as trains cross slowly—the signature view here."
],
"傍晚是最推薦的時段：夕陽把天空與河面染成粉橘色，列車的剪影從橋上滑過，倒影在水面輕輕晃動。春天沿岸的櫻花盛開，秋天則換上一整排楓紅，一年四季各有不同的表情。從多見瀨站下車後，沿著河岸走即可到達。": [
"おすすめは夕方。夕日が空と川面を桃色がかった橙に染め、列車のシルエットが橋の上をすべり、水面に映る影が静かに揺れます。春は川沿いの桜が満開になり、秋は紅葉が並び、一年を通して表情が変わります。多見瀨駅を降りたら、川岸に沿って歩けば着きます。",
"Evening is the best time: the sunset tints sky and river pink-orange, a train’s silhouette glides over the bridge, and its reflection sways gently on the water. Cherry blossoms line the banks in spring and maples in autumn, so the scene changes through the year. From Tomise station, simply walk along the river."
],
