"紀念・歷史": [
"記念・歴史",
"Memorial · History"
],
"雄武的飛鳥雕像，紀念 1947 年立憲運動與和平民主化。": [
"勇ましい飛鳥の像が、1947年の立憲運動と平和的民主化を記念しています。",
"A valiant bird statue commemorates the 1947 constitutional movement and peaceful democratization."
],
"平倉市革命紀念公園是為了紀念 1947 年的立憲運動而設立的公園。園內矗立著一座雄武的飛鳥雕像，展開的雙翼象徵人民追求自由與和平的意志，也象徵這座城市從此走上民主的道路。": [
"平倉市革命記念公園は、1947年の立憲運動を記念して作られた公園です。園内には勇ましい飛鳥の像がそびえ、広げた翼は自由と平和を求める人々の意志を、そしてこの街がその後民主の道を歩み始めたことを象徴しています。",
"Hekura City Revolution Memorial Park was created to commemorate the 1947 constitutional movement. A valiant bird statue rises in the park; its outspread wings symbolize people’s will for freedom and peace and the city’s subsequent path to democracy."
],
"公園腹地寬廣，草坪與樹木環繞著雕像，晴天的藍天與白色雕像形成鮮明的對比。鐵道從公園旁經過，雕像和列車常常同時入鏡，是拍照的熱門地點。從平倉公園西站或東平倉站都可以步行前往。": [
"公園は広く、芝生と木々が像を囲み、晴れた日の青空と白い像が鮮やかな対比をなします。鉄道は公園のそばを通り、像と列車が同じ写真に収まることも多く、人気の撮影スポットです。平倉公園西駅または東平倉駅から歩いて行けます。",
"The park is spacious, with lawns and trees around the statue; on sunny days the blue sky contrasts vividly with the white statue. The railway passes beside the park, so the statue and a train often fit in the same shot—a popular photo spot. A walk from Hekura-koen-nishi or Higashi-Hekura station."
],
