"競技場內開放作冰宮的白色冰面與看台": [
"アイスパレスとして開放されたアリーナの白い氷面と客席",
"The white ice and stands of the arena opened as an ice palace"
],
"現代美術展館與劇場合一，不定時有音樂劇演出。": [
"現代美術の展示と劇場を備え、不定期にミュージカルも上演。",
"Modern art galleries and a theatre in one building, with occasional musicals."
],
"懷永美術館是一座現代美術館，館內除了現代美術的展覽空間，還設有戲劇會場。深色的外牆與落地玻璃，從車站月台的屋頂上方就能看見整座建築。": [
"懐永美術館は現代美術館で、館内には現代美術の展示スペースのほか、劇場も備えています。濃色の外壁と大きなガラス窓の建物は、駅ホームの屋根越しにも見渡せます。",
"Kaiei Museum of Art is a modern art museum with both exhibition space and a theatre. Its dark walls and large glass windows can be seen above the station platform roofs."
],
"戲劇會場以木質的座席與天花板為特色，舞台上的佈景會隨演出更換，不定時會有音樂劇上演。逛完展覽再看一場演出，是適合半天到一天的行程。最近車站是曲江站。": [
"劇場は木質の客席と天井が特徴で、舞台の背景は演目ごとに入れ替わり、不定期にミュージカルが上演されます。展示を見たあとに公演を楽しむ、半日から1日のコースにおすすめです。最寄駅は曲江駅です。",
"The theatre is known for its wooden seats and ceiling; stage sets change with each production, and musicals are staged from time to time. Combine an exhibition with a show for a half-day or full-day outing. The nearest station is Magarie."
],
