"高 270 公尺的觀景塔，位於光瀨市中心的中央公園，可眺望市區風景。": [
"高さ270メートルの展望塔。光瀬市中心部の中央公園にあり、市街地を一望できます。",
"A 270 m observation tower in Central Park in the middle of Hikarise, with views over the city."
],
"流星樹是光瀨市中心最醒目的地標，高 270 公尺，矗立在中央公園內。塔身向上收窄，頂端的環形展望台像一圈光環，從市區各處都看得見。": [
"流星樹は光瀬市中心部で最も目立つランドマークで、高さ270メートル。中央公園にそびえています。塔身は上に向かって細くなり、頂上のリング状の展望台は光の輪のように、市内のあちこちから見えます。",
"Ryusei Tree is the most striking landmark in central Hikarise, 270 m tall in Central Park. The shaft narrows upwards and the ring-shaped observation deck at the top looks like a halo, visible from all over the city."
],
"白天可以從展望台俯瞰光瀨市街與鐵道，晴朗的日子視野最好；入夜後塔身中央的光帶亮起，與周圍的高樓一同點亮夜空，是拍夜景的好地點。從みつせ站步行即可抵達。": [
"昼は展望台から光瀬の街並みと鉄道を見下ろせ、晴れた日は眺めが抜群です。夜は塔身中央の光の帯が灯り、周囲の高層ビルとともに夜空を彩ります。夜景撮影にもおすすめ。みつせ駅から歩いて行けます。",
"By day you can look down on the city and railway from the deck, best on a clear day. At night a band of light glows along the shaft and, with the surrounding towers, lights up the sky — a great spot for night photos. Walk from Mitsuse Station."
],
