"Cars 1 and 2 are business class (1+2 layout): Car 1 has 4 rows of 12 seats, Car 2 has 12 rows of 36 seats. Cars 3–8 are standard class (2+2 layout); Car 8 (rear) has 8 seats (2 rows), the rest have 40 seats each"
