"2006 年 12 月通車的這條線，在 2018 年因為經營不善停止營運，月台空了八年。2026 年，光瀨市交通局接手，讓它重新出發——帶著這座城市一直沒有放棄的期待。": ["2006年12月に開業したこの路線は、2018年に経営難で運行を停止し、ホームは八年のあいだ静かなままでした。2026年、光瀨市交通局が運営を引き継ぎ、この街がずっと手放さなかった願いとともに、もう一度走り出します。", "Opened in December 2006, this line stopped running in 2018 after its operator ran into trouble, and the platforms stood empty for eight years. In 2026 the Hikarise City Transportation Bureau took it over, and it sets out again — carrying the hope this city never let go of."],
