"光瀨市交通局接手營運": ["光瀨市交通局が運営を継承", "Hikarise City Transportation Bureau takes over operations"],
"恢復營業運轉": ["営業運転　再開", "Revenue service resumes"],
"八年的空白不是終點。光瀨市交通局接手之後，全線均一運賃、與光瀨都市鉄道共通的優惠票券，都是為了讓這條線重新成為市民的日常。": ["八年の空白は終わりではありませんでした。光瀨市交通局が引き継いだあとの全線均一運賃も、光瀨都市鉄道と共通の割引きっぷも、この路線をもう一度、市民の日常に戻すためのものです。", "Eight blank years were not the end. The flat system-wide fare and the passes shared with the Hikarise Urban Railway are both there to make this line part of everyday life again."],
