"懸垂式單軌是什麼？": ["懸垂式モノレールとは？", "What is a suspended monorail?"],
"軌道梁：下方開口的鋼製箱型梁": ["軌道桁：下面が開いた鋼製の箱形桁", "Guideway beam: a steel box girder open at the bottom"],
"台車：走行輪與案內輪都藏在梁裡": ["台車：走行輪と案内輪は桁の中", "Bogie: running and guide wheels run inside the beam"],
"懸垂連結：把車體吊在台車下方": ["懸垂装置：車体を台車の下につり下げる", "Hanger: suspends the car body from the bogie"],
"車體": ["車体", "Car body"],
"支柱": ["支柱", "Pillar"],
"懸垂式單軌的車輛吊在軌道梁「下方」行駛。車輪在梁內，不受雨雪影響，也不會碰到地面的車流；轉彎時車體會自然地微微擺動。": ["懸垂式モノレールの車両は軌道桁の「下」につり下がって走ります。車輪は桁の中にあるので雨や雪の影響を受けにくく、地上の交通とも交わりません。カーブでは車体が自然にわずかに揺れます。", "A suspended monorail hangs below its guideway beam. The wheels run inside the beam, so rain and snow affect them less and the train never meets road traffic; on curves the car body sways slightly."],
"從正下方看懸垂式單軌：車體吊在軌道梁下。": ["真下から見た懸垂式モノレール。車体が軌道桁につり下がっています。", "Seen from directly below: the car hangs from the guideway beam."],
"月台上的先頭部與發車案內。": ["ホームに停車中の先頭部と発車案内。", "The front car at the platform with the departure board."],
"十字路口上空的軌道梁。": ["交差点の上空を通る軌道桁。", "The guideway beam above a crossroads."],
"HIKACARD（¥1,500，內含儲值 ¥500）。與光瀨都市鉄道共通，進出站感應即可。": ["HIKACARD（1,500 円、うちチャージ 500 円）。光瀨都市鉄道と共通で、改札でタッチするだけです。", "HIKACARD (¥1,500 including ¥500 stored value). Shared with Mitsuse Hikarise Railways — just tap in and out."],
"詳細介紹": ["詳しくはこちら", "Details"],
"在自動售票機購買車票，或在剪票口感應 HIKACARD 進站。": ["自動券売機できっぷを買うか、改札で HIKACARD をタッチして入場します。", "Buy a ticket at the machine, or tap HIKACARD at the gate to enter."],
"HIKACARD 的介紹暫時無法顯示。": ["HIKACARD のご案内は現在表示できません。", "The HIKACARD information can't be shown right now."],
"十字路口上空的單軌軌道梁": ["交差点の上空を通るモノレールの軌道桁", "Monorail guideway beam above a crossroads"],
"八幡通站的高架月台與兩列 CITYMOVER": ["八幡通駅の高架ホームと 2 本の CITYMOVER", "Two CITYMOVER trains at the elevated Hachiban-dori platforms"],
"夕陽下從正下方仰望的懸垂式單軌": ["夕日の中、真下から見上げた懸垂式モノレール", "A suspended monorail seen from below at sunset"],
"月台上的單軌列車先頭部與發車案內": ["ホームに停車中のモノレール先頭部と発車案内", "The monorail's front car and departure board at the platform"],
