"找不到直達或轉乘一次可以到達的公車。請改用光瀨都市鉄道或單軌，或換一個站牌查詢。": ["直通または乗換1回で行けるバスが見つかりません。光瀨都市鉄道・モノレールをご利用いただくか、別の停留所でお調べください。", "No direct or one-transfer bus found. Try Hikarise Railway or the monorail, or another stop."],
"◎＝可轉乘光瀨都市鉄道・單軌的站牌。位置為示意，並非實際道路。": ["◎＝光瀨都市鉄道・モノレールに乗り換えられる停留所。位置は模式的で、実際の道路ではありません。", "◎ = stops with transfer to Hikarise Railway / monorail. Positions are schematic, not actual roads."],
"光瀨市交通局的市營公車，以みつせ、戸宮、花倉街道、東平倉、紫市、名島港、勝守、十万浦市、上羽神別為中心運行。": ["光瀨市交通局の市営バスは、みつせ・戸宮・花倉街道・東平倉・紫市・名島港・勝守・十万浦市・上羽神別を中心に運行しています。", "Hikarise City Transportation Bureau's municipal buses run around Mitsuse, Tomiya, Hanakura-Kaido, Higashi-Hirakura, Murasaki City, Najima Port, Katsumori, Juman'ura City and Kamiba-Kanbetsu."],
"營運時間 04:00～24:30。06:00～09:00 與 15:00～19:00 每 15 分一班，09:00～15:00 每 30 分一班，其餘時段每 45 分一班。可以使用 HIKACARD。": ["運行時間 4:00〜24:30。6:00〜9:00と15:00〜19:00は15分間隔、9:00〜15:00は30分間隔、その他の時間帯は45分間隔です。HIKACARDがご利用いただけます。", "Service 04:00–24:30. Every 15 min 06:00–09:00 and 15:00–19:00, every 30 min 09:00–15:00, every 45 min at other times. HIKACARD accepted."],
