"◎＝可轉乘光瀨都市鉄道・單軌的站牌。點路線號可以只看那一條。圖為方格示意，並非實際道路與方位。": ["◎＝光瀨都市鉄道・モノレールに乗り換えられる停留所。系統番号を押すとその系統だけを表示します。図は方眼の模式図で、実際の道路・方位とは異なります。", "◎ = stops with transfer to Hikarise Railway / monorail. Tap a route number to show only that route. Schematic grid, not actual roads or bearings."],
