"滝井川、五原、御笠市 一車直達。新 8000 形 2000 番台，最高時速 160 公里，全車指定席。": ["滝井川・五原・御笠市へ乗り換えなしで直通。新8000形2000番台、最高速度160km/h、全車指定席。", "Direct to Takiigawa, Goen and Mikasa with no changes. New 8000 Series 2000s, top speed 160 km/h, all cars reserved."],
