"咲海研究學園都市、松澤國際空港方面": ["咲海研究学園都市・松沢国際空港方面", "Toward Seiumi Science City and Matsuzawa International Airport"],
"特急スーパーしらたか 登場 花川本線 御笠市延伸，滝井川、五原、御笠市一車直達（新 8000 形 2000 番台）": ["特急スーパーしらたか デビュー　花川本線が御笠市まで延伸、滝井川・五原・御笠市へ直通（新8000形2000番台）", "Ltd. Exp. Super Shirataka debuts: the Hanakawa Main Line now reaches Mikasa, with direct trains to Takiigawa, Goen and Mikasa (New 8000 Series 2000s)"],
"御笠市的中心車站，也是花川本線的終點。特急スーパーしらたか從松澤國際空港、東平倉一車直達，站前有市公所、商店街與公車轉運站，是天照地方的玄關。": ["御笠市の中心駅で、花川本線の終点です。特急スーパーしらたかが松沢国際空港・東平倉から直通し、駅前には市役所、商店街、バスターミナルが集まる天照地方の玄関口です。", "The central station of Mikasa and the terminus of the Hanakawa Main Line. The Ltd. Exp. Super Shirataka runs here directly from Matsuzawa International Airport and Higashi-Hekura, and the city hall, shopping streets and bus terminal around the station make it the gateway to the Tensho Region."],
"御笠一帶早年以煤礦聞名，山裡的炭坑支撐了整座城市的發展，運煤的貨物線與選煤場就設在今天的車站周邊。閉山之後，城市轉型為漁業與觀光的據點，站前的老喫茶店和食堂裡，還看得到炭坑時代的照片。": ["御笠はかつて石炭の町として知られ、山あいの炭鉱が街の発展を支えました。石炭を運ぶ貨物線や選炭場は、いまの駅の周辺にありました。閉山後は漁業と観光の拠点へと姿を変え、駅前の古い喫茶店や食堂には今も炭鉱時代の写真が飾られています。", "Mikasa was once known as a coal town: the mines in the hills powered its growth, and the coal freight line and coal-preparation plant stood around today's station. After the mines closed the city turned to fishing and tourism, and photos from the mining era still hang in the old cafes and canteens in front of the station."],
"御笠的外海是寒流與暖流交會的漁場，自古被稱為海產的聖地。從車站東口步行約 10 分鐘就是御笠漁港，每天清晨漁市場都有拍賣，旁邊的市場食堂可以吃到剛上岸的海膽、鮭魚卵與毛蟹。": ["御笠の沖は寒流と暖流がぶつかる好漁場で、昔から海の幸の聖地と呼ばれてきました。駅東口から徒歩約10分の御笠漁港では毎朝せりが行われ、隣の市場食堂では水揚げされたばかりのうに、いくら、毛蟹が味わえます。", "Off Mikasa, cold and warm currents meet to form rich fishing grounds, long called a paradise for seafood. Mikasa Fishing Port is about a 10-minute walk from the East Exit; auctions are held every morning, and the market canteen next door serves freshly landed sea urchin, salmon roe and hairy crab."],
"御笠市站的跨站式站房與站前廣場": ["御笠市駅の橋上駅舎と駅前広場", "The bridge-style station building and plaza of Mikasa-shi Station"],
