"石橋與河面倒影，傍晚最好拍": ["石橋と川面の映り込み、夕方がおすすめ", "The stone bridge and reflections — best in the evening"],
"俯瞰千歲川水圳與石橋": ["千歳川の水路と石橋を見下ろす", "Overlooking the Chitose River canal and stone bridge"],
"水圳與石橋": ["水路と石橋", "Canal and stone bridge"],
